import random, collections
def stat(blocks,stop,policy):
 c=collections.Counter()
 for b in blocks:
  if policy=='compress': seq=[w for w in b if w not in stop]
  else:seq=[None if w in stop else w for w in b]
  for i,a in enumerate(seq):
   if a is None:continue
   for v in seq[i+1:i+4]:
    if v is None: break
    if a!=v:c[a,v]+=1
 pairs={tuple(sorted((a,b))) for a,b in c};skew=sum(abs(c[a,b]-c[b,a])>5 for a,b in pairs);n=sum(c.values());return {'type_ratio':skew/len(pairs) if pairs else 0,'skewed_types':skew,'pair_types':len(pairs),'pair_occurrences':n,'instance_ratio':skew/n if n else 0}
def measurement(blocks,seed):
 flat=[w for b in blocks for w in b];counts=collections.Counter(flat);stops=set(w for w,n in sorted(counts.items(),key=lambda p:(-p[1],p[0]))[:1]);kept=[w for w in flat if w not in stops];freq=collections.Counter(kept);rng=random.Random(seed);res={}
 for policy in ('compress','barrier'):
  observed=stat(blocks,stops,policy);null=[]
  for _ in range(99):
   draws=[]
   for b in blocks:
    c=b.copy();rng.shuffle(c);draws.append(c)
   null.append(stat(draws,stops,policy)['type_ratio'])
  res[policy]={'observed':observed,'null_mean':sum(null)/len(null),'null_min':min(null),'null_max':max(null),'p':(1+sum(x>=observed['type_ratio'] for x in null))/(1+len(null))}
 return {'types_per_token':len(freq)/len(kept),'hapax_per_token':sum(c==1 for c in freq.values())/len(kept),'retained_tokens':len(kept),'policies':res}


